const mesasResp = $('Get Mesas').item.json;
const reservationsResp = $('Get Day Reservations').item.json;
const parse = $('Parse Time & Service').item.json;

// ── DEBUG ──
console.log('[CALC_DEBUG] mesasResp type:', typeof mesasResp, 'keys:', Object.keys(mesasResp || {}));
console.log('[CALC_DEBUG] reservationsResp type:', typeof reservationsResp, 'keys:', Object.keys(reservationsResp || {}));
console.log('[CALC_DEBUG] mesasResp.error:', mesasResp?.error?.status || mesasResp?.error?.code || 'none');
console.log('[CALC_DEBUG] reservationsResp.error:', reservationsResp?.error?.status || reservationsResp?.error?.code || 'none');
if (mesasResp?.documents) console.log('[CALC_DEBUG] mesas docs:', mesasResp.documents.length);
else console.log('[CALC_DEBUG] mesas NO documents');
if (reservationsResp?.documents) console.log('[CALC_DEBUG] reservations docs:', reservationsResp.documents.length);
else console.log('[CALC_DEBUG] reservations NO documents');
console.log('[CALC_DEBUG] parse:', JSON.stringify(parse));
// ── END DEBUG ──

const requestedPartySize = parse.partySize || 2;
const requestedDate = parse.reservation_date;
const requestedService = parse.reservation_service;
const requestedTime = parse.reservation_time;

// ── Helpers ──
const extractDocuments = (data) => {
  if (!data) return [];
  if (Array.isArray(data)) return data;
  if (data.documents && Array.isArray(data.documents)) return data.documents;
  if (data.items && Array.isArray(data.items)) return data.items;
  if (data.body) return extractDocuments(data.body);
  if (data.data) return extractDocuments(data.data);
  return [];
};

const extractField = (item, key) => {
  if (!item) return null;
  if (item.fields && item.fields[key]) {
    const f = item.fields[key];
    return f.stringValue !== undefined ? f.stringValue :
           f.integerValue !== undefined ? parseInt(f.integerValue) :
           f.booleanValue !== undefined ? f.booleanValue :
           f.doubleValue !== undefined ? parseFloat(f.doubleValue) : null;
  }
  return item[key] !== undefined ? item[key] : null;
};

const extractId = (item) => {
  if (!item) return '';
  if (item.id) return item.id;
  if (item.name) return item.name.split('/').pop();
  return '';
};

const normalizePhone = (p) => {
  if (!p) return '';
  return String(p).replace(/@s\.whatsapp\.net$/i, '').replace(/[^0-9]/g, '');
};

const t2m = (time, svc) => {
  if (!time) return 0;
  const [h, m] = time.split(':').map(Number);
  if (svc === 'cena' && h < 12) return (h + 24) * 60 + m;
  return h * 60 + m;
};

// ── Check HTTP errors ──
if (mesasResp && mesasResp.error) {
  console.log('[Calc Availability] Get Mesas error:', mesasResp.error.message || mesasResp.error.status || JSON.stringify(mesasResp.error));
}
if (reservationsResp && reservationsResp.error) {
  console.log('[Calc Availability] Get Reservations error:', reservationsResp.error.message || reservationsResp.error.status || JSON.stringify(reservationsResp.error));
}

const mesasDocs = extractDocuments(mesasResp);
const reservationDocs = extractDocuments(reservationsResp);

const mesasArray = mesasDocs.map(m => ({
  id: extractId(m),
  name: extractField(m, 'name') || `M${extractId(m).replace('m', '')}`,
  capacity: parseInt(extractField(m, 'capacity') || 0),
}));

const reservationsArray = reservationDocs.map(r => ({
  id: extractId(r),
  tableId: extractField(r, 'tableId') || '',
  date: extractField(r, 'date'),
  service: extractField(r, 'service'),
  time: extractField(r, 'time'),
  duration: parseInt(extractField(r, 'duration')) || 0,
  estado: extractField(r, 'estado') || '',
  liveState: extractField(r, 'liveState') || '',
  customerPhone: normalizePhone(extractField(r, 'customerPhone') || extractField(r, 'phone')),
}));

const rawPhone = parse.phone || $('Webhook1').item.json.body.data.key.remoteJid || '';
const phone = normalizePhone(rawPhone);

// ── Duplicate check ──
const isDuplicate = phone && reservationsArray.some(r =>
  r.customerPhone === phone &&
  r.service === requestedService &&
  r.date === requestedDate
);

if (isDuplicate) {
  return [{
    json: {
      has_availability: false,
      assigned_table: null,
      assigned_table_name: null,
      assigned_table_capacity: null,
      free_tables: 0,
      free_suitable_tables: 0,
      total_tables: mesasArray.length,
      occupied_tables: mesasArray.length,
      requested_party_size: requestedPartySize,
      requested_time: requestedTime,
      requested_date: requestedDate,
      requested_service: requestedService,
      customerName: parse.customerName || '',
      phone: phone,
      notes: parse.notes || '',
      reservation_estado: 'pendiente',
      customerPhone: phone,
      duplicate_error: true,
    }
  }];
}

// ── States that don't occupy a table ──
const inactiveEstados = ['cancelado', 'no_show', 'ausente'];
const inactiveLiveStates = ['liberada', 'finalizado'];

// ── Build occupied set with state filter + time overlap ──
const occupiedTableIds = new Set();
reservationsArray.forEach(r => {
  if (!r.tableId || r.date !== requestedDate || r.service !== requestedService || r.tableId === '') return;
  if (inactiveEstados.includes(r.estado)) return;
  if (inactiveLiveStates.includes(r.liveState)) return;

  const rStart = t2m(r.time, requestedService);
  const rEnd = rStart + (r.duration || (requestedService === 'cena' ? 120 : 90));
  const reqStart = t2m(requestedTime, requestedService);
  const reqDuration = requestedService === 'cena' ? 120 : 90;
  const reqEnd = reqStart + reqDuration;

  if (reqStart < rEnd && reqEnd > rStart) {
    occupiedTableIds.add(r.tableId);
  }
});

// ── If mesas data failed (HTTP error), fall back to optimistic: create reservation without table ──
const hasHttpError = mesasResp?.error != null || reservationsResp?.error != null;
if (hasHttpError) {
  return [{
    json: {
      has_availability: true,
      assigned_table: null,
      assigned_table_name: null,
      assigned_table_capacity: null,
      free_tables: 0,
      free_suitable_tables: 0,
      total_tables: 0,
      occupied_tables: 0,
      requested_party_size: requestedPartySize,
      requested_time: requestedTime,
      requested_date: requestedDate,
      requested_service: requestedService,
      customerName: parse.customerName || '',
      phone: phone,
      notes: parse.notes || '',
      reservation_estado: 'pendiente',
      customerPhone: phone,
      duplicate_error: false,
      http_error: true,
    }
  }];
}

const freeMesas = mesasArray
  .filter(m => !occupiedTableIds.has(m.id) && m.capacity >= requestedPartySize)
  .sort((a, b) => a.capacity - b.capacity);

const hasAvailability = freeMesas.length > 0;
const assignedTable = hasAvailability ? freeMesas[0] : null;

return [{
  json: {
    has_availability: hasAvailability,
    assigned_table: assignedTable ? assignedTable.id : null,
    assigned_table_name: assignedTable ? assignedTable.name : null,
    assigned_table_capacity: assignedTable ? assignedTable.capacity : null,
    free_tables: mesasArray.filter(m => !occupiedTableIds.has(m.id)).length,
    free_suitable_tables: freeMesas.length,
    total_tables: mesasArray.length,
    occupied_tables: occupiedTableIds.size,
    requested_party_size: requestedPartySize,
    requested_time: requestedTime,
    requested_date: requestedDate,
    requested_service: requestedService,
    customerName: parse.customerName || '',
    phone: phone,
    notes: parse.notes || '',
    reservation_estado: hasAvailability ? 'confirmada' : 'pendiente',
    customerPhone: phone,
    duplicate_error: false,
  }
}];

const data = $('Calc Availability').item.json;

if (data.http_error || data.error) {
  return [{
    json: {
      error: true,
      error_message: 'Lo sentimos, ocurri\u00f3 un error al procesar tu solicitud. Por favor, intent\u00e1 de nuevo m\u00e1s tarde.',
    }
  }];
}

if (data.duplicate_error) {
  return [{
    json: {
      error: true,
      error_message: `Ya tenés una reserva para el ${data.requested_date} en turno ${data.requested_service === 'mediodia' ? 'Mediodía' : 'Cena'}. No podés reservar dos veces.`,
    }
  }];
}

const id = `r${Date.now()}`;
const now = new Date().toLocaleString('sv-SE', { timeZone: 'America/Argentina/Buenos_Aires' }).replace(' ', 'T');
const mesaResId = data.assigned_table ? `${data.assigned_table}_${data.requested_date}_${data.requested_service}` : null;

const toFirestoreFields = (obj) => {
  const fields = {};
  for (const [k, v] of Object.entries(obj)) {
    if (v === null || v === undefined) {
      fields[k] = { stringValue: '' };
    } else if (typeof v === 'number') {
      fields[k] = Number.isInteger(v) ? { integerValue: v } : { doubleValue: v };
    } else if (typeof v === 'boolean') {
      fields[k] = { booleanValue: v };
    } else {
      fields[k] = { stringValue: String(v) };
    }
  }
  return fields;
};

const reservationData = {
  id,
  customerName: data.customerName,
  phone: data.phone,
  partySize: data.requested_party_size,
  tableId: data.assigned_table || '',
  mesa_id: data.assigned_table || '',
  time: data.requested_time,
  duration: data.requested_service === 'cena' ? 120 : 90,
  service: data.requested_service,
  notes: data.notes || '',
  liveState: '',
  startedAt: '',
  leftAt: '',
  date: data.requested_date,
  estado: data.reservation_estado,
  source: 'whatsapp',
  customerPhone: data.customerPhone,
  staffId: '',
  staffName: '',
  createdAt: now,
  updatedAt: now,
};

const mesaResData = data.assigned_table ? {
  occupied: true,
  reservationId: id,
  time: data.requested_time,
  partySize: data.requested_party_size,
} : null;

return [{
  json: {
    reservation_id: id,
    flat_doc: { fields: toFirestoreFields(reservationData) },
    mesa_res_id: mesaResId,
    mesa_res_doc: mesaResData ? { fields: toFirestoreFields(mesaResData) } : null,
    has_availability: data.has_availability,
    has_table: data.assigned_table !== null,
    assigned_table_name: data.assigned_table ? `M${data.assigned_table.replace('m', '')}` : null,
    requested_party_size: data.requested_party_size,
    requested_time: data.requested_time,
    requested_date: data.requested_date,
    customerName: data.customerName,
  }
}];

const data = $('Prepare Reservation').item.json;

let mensaje;
if (data.has_table) {
  mensaje = `✅ *¡Reserva confirmada!*

📍 Mesa: *${data.assigned_table_name}*
👤 ${data.customerName} · ${data.requested_party_size} personas
📅 ${data.requested_date} a las ${data.requested_time}

Te esperamos en *Andi*. ¡Hasta pronto! 🍽️`;
} else {
  mensaje = `⏳ *Reserva recibida*

👤 ${data.customerName} · ${data.requested_party_size} personas
📅 ${data.requested_date} a las ${data.requested_time}

No encontramos mesa disponible para ese horario. Te contactaremos pronto para confirmar. 🙏`;
}

return [{ json: { mensaje } }];

const data = $('Calc Availability').item.json;
const serviceLabel = data.requested_service === 'mediodia' ? 'mediod\u00eda' : 'cena';
const timeStr = data.requested_time || '';
const dateStr = data.requested_date || '';
const pax = data.requested_party_size || 0;

if (data.http_error) {
  const msg = '\u26a0\ufe0f Hubo un error al verificar la disponibilidad. Por favor, intent\u00e1 de nuevo m\u00e1s tarde.';
  return [{ json: { mensaje: msg } }];
}

if (data.has_availability && data.assigned_table) {
  const msg = '\u2705 \u00a1Hay disponibilidad!\\n\\n\ud83d\udccd Mesa: *${data.assigned_table_name}*\\n\ud83d\udcc5 ${dateStr} a las ${timeStr}\\n\ud83d\udc64 ${pax} personas\\n\\n\u00bfQuer\u00e9s que reserve esa mesa?';
  return [{ json: { mensaje: msg } }];
}

const msg = '\u274c No hay mesas disponibles para ${serviceLabel} el ${dateStr} para ${pax} personas. Pod\u00e9s probar otro horario o fecha.';
return [{ json: { mensaje: msg } }];
